import { URI } from "vscode-uri";
import { DEngineClient } from "./types";
import { DVault } from "./DVault";
import { SailConfig } from "./configs";
import { RemoteEndpoint } from "./RemoteEndpoint";

export enum WorkspaceType {
  NATIVE = "NATIVE",
  CODE = "CODE",
  NONE = "NONE",
}

export type DWorkspaceLegacy = {
  name: string;
  vaults: DVault[];
  remote: RemoteEndpoint;
};

export type DWorkspaceEntry = Omit<DWorkspaceLegacy, "name" | "vaults">;


export type DWorkspaceV2 = {
  /**
   * Absolute path to the workspace directory
   */
  wsRoot: string;
  type: WorkspaceType;
  config: SailConfig;
  vaults: DVault[];
  engine: DEngineClient;
  /**
   * Where are assets stored (eg. tutorial workspace)
   */
  assetUri: URI;
  /**
   * Log storage
   */
  logUri: URI;
};

/**
 * Extension Install Status
 */
export enum InstallStatus {
  NO_CHANGE = "NO_CHANGE",
  INITIAL_INSTALL = "INITIAL_INSTALL",
  UPGRADED = "UPGRADED",
}
